lib:
// 目录/正文的分页地址拼绝对路径（结果是 // 开头时补 https:）
fn hhAbs(u, base) {
  let s = str(u)
  if (s == '') { return '' }
  if (match(s, '^(https?://)', 1) != '') { return s }
  if (match(s, '^//', 1) != '') { return 'https:' + s }
  if (match(s, '^/', 1) != '') { return str(base) + s }
  return str(base) + '/' + s
}
// 搜索结果的书名带 [类别] 前缀，取方括号里的类别；没有方括号返回空
fn hhKind(s) {
  let t = str(s)
  if (substring(t, 0, 1) != '[') { return '' }
  let a = split(t, ']')
  if (len(a) < 1) { return '' }
  let x = str(a[0])
  if (len(x) < 2) { return '' }
  return substring(x, 1, len(x))
}
// 目录分页：站点只有数字页码、没有下一页链接，从 active 页码推出 index_{n+1}.html，读 1/N 判尾
fn hhTocNext(html, base) {
  let h = str(html)
  let cur = match(h, 'page-item[^>]*active[^>]*>[^<]*<a[^>]*href="([^"]+)"', 1)
  let tot = match(h, 'page-link[^>]*>([0-9]+)/([0-9]+)<', 2)
  if (cur == '' || tot == '') { return '' }
  let n = int(match(cur, 'index_([0-9]+)[.]html', 1), 0)
  let t = int(tot, 0)
  if (n < 1 || t < 2 || n >= t) { return '' }
  return hhAbs(replace(cur, '[0-9]+[.]html$', str(n + 1) + '.html', 'g'), base)
}
// 章内续页：只放行 *_N.html；命中「下一章」时返回空，避免把下一章拼进正文
fn hhNextArt(html, base) {
  let href = match(str(html), 'id="next"[^>]*href="([^"]+)"', 1)
  if (href == '') { return '' }
  if (match(href, '_[0-9]+[.]html$', 1) == '') { return '' }
  return hhAbs(href, base)
}
